Add, through storeAction() as CLAUDE.md asks of every server action (import storeAction from '@/server/store-action', latestDreamRun from '@/server/dream-factory', createHash from 'node:crypto'):

/** The Dream Factory's poll (bloat review step 0.17): a short fingerprint of the store's latest run, so the page redraws only when it changed. Refreshes nothing, so no page is sent back. */
export async function dreamStateAction(storeSlug: string): Promise<string | null> {
  return storeAction({ store: storeSlug, key: "owner", action: "dream.state", answer: () => null }, async (member) => {
    const run = await latestDreamRun(member.store.id);
    if (!run) return "none";
    return createHash("sha256").update(JSON.stringify([run.id, run.status, run.readyAt, run.finishedAt, run.steps])).digest("hex").slice(0, 16);
  });
}

The key "owner" is the same check the file's owner() makes. It must NOT call revalidatePath(), refresh() or answer(): an action that refreshes nothing sends no page back.

A new int test file of its own (so its mock touches no other case). db() in src/db/client.ts returns a Proxy whose `execute` is made anew on each read, so vi.spyOn cannot count it; typedRows() calls db().execute when given no executor, so a wrapping mock counts it. Content, exactly:

import { sql } from "drizzle-orm";
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("server-only", () => ({}));
vi.mock("next/cache", () => ({ cacheLife: () => {}, cacheTag: () => {}, updateTag: () => {}, revalidateTag: () => {}, refresh: () => {} }));
vi.mock("next/server", () => ({ connection: async () => {}, after: () => {} }));
const sent = vi.hoisted(() => ({ n: 0 }));
vi.mock("@/db/client", async (original) => {
  const real = await original<typeof import("@/db/client")>();
  return {
    ...real,
    db: () => new Proxy(real.db(), { get(target, property, receiver) { if (property === "execute") return (query: never) => { sent.n += 1; return target.execute(query); }; return Reflect.get(target, property, receiver); } }),
  };
});

const { closeDb, db } = await import("@/db/client");
const { makeStore } = await import("./trust-fixtures");
const notices = await import("./assistant-notices");

/** The notice badge's count (bloat review step 0.17): with the route's account read, 2 statements (4 before: the account, the store by slug, a list of one, the count). Step 1.9's counter replaces this wrapper. */
let store: Awaited<ReturnType<typeof makeStore>>;

beforeAll(async () => {
  store = await makeStore("notice-count");
  await notices.addNotice({ accountId: store.account.id, storeId: store.id, notice: "page_built", ref: "count-1", path: "pages/abc", facts: { title: "About us" } });
});

afterAll(async () => {
  await db().execute(sql`delete from commerce.assistant_notices where account_id = ${store.account.id}::uuid`);
  await closeDb();
});

describe("the notice badge", () => {
  it("the badge's count is one statement", async () => {
    sent.n = 0;
    expect(await notices.unreadNotices(store.account.id, store.id)).toBe(1);
    expect(sent.n).toBe(1);
  });
});

If sent.n is 0 (the wrapper saw nothing) the stop_if applies.
